function oddEvenGcd(n: number): number {
  let a = 0, b = 0;
  for (let i = 1; i <= n; i++) {
    a += 2 * i - 1;
    b += 2 * i;
  }
  while (b !== 0) [a, b] = [b, a % b];
  return a;
}

